import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"莺啼序·残寒正欺病酒","description":"","frontmatter":{"title":"莺啼序·残寒正欺病酒","date":"2026-11-10T00:00:00.000Z","seq":9,"categories":["美文","宋词三百首"],"collection":"《宋词三百首》","tags":["宋词三百首","宋"],"poem":true,"author":"吴文英","source_book":"宋词三百首"},"headers":[],"relativePath":"blogs/宋词三百首/莺啼序·残寒正欺病酒.md","filePath":"blogs/宋词三百首/莺啼序·残寒正欺病酒.md"}'),o={name:"blogs/宋词三百首/莺啼序·残寒正欺病酒.md"};function c(l,a,n,_,m,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="莺啼序·残寒正欺病酒" tabindex="-1">莺啼序·残寒正欺病酒 <a class="header-anchor" href="#莺啼序·残寒正欺病酒" aria-label="Permalink to &quot;莺啼序·残寒正欺病酒&quot;">​</a></h1><p class="poem-meta">宋 · 吴文英</p><div class="poem"><p class="poem-stanza">残寒正欺病酒，掩沈香绣户。</p><p class="poem-stanza">燕来晚、飞入西城，似说春事迟暮。</p><p class="poem-stanza">画船载、清明过却，晴烟冉冉吴宫树。</p><p class="poem-stanza">念羁情游荡，随风化为轻絮。</p><p class="poem-stanza">十载西湖，傍柳系马，趁娇尘软雾。</p><p class="poem-stanza">溯红渐、招入仙溪，锦儿偷寄幽素。</p><p class="poem-stanza">倚银屏、春宽梦窄，断红湿、歌纨金缕。</p><p class="poem-stanza">暝堤空，轻把斜阳，总还鸥鹭。</p><p class="poem-stanza">幽兰旋老，杜若还生，水乡尚寄旅。</p><p class="poem-stanza">别后访、六桥无信，事往花委，瘗玉埋香，几番风雨。</p><p class="poem-stanza">长波妒盼，遥山羞黛，渔灯分影春江宿，记当时、短楫桃根渡。</p><p class="poem-stanza">青楼彷佛，临分败壁题诗，泪墨惨澹尘土。</p><p class="poem-stanza">危亭望极，草色天涯，吹鬓侵半苎。</p><p class="poem-stanza">暗点检、离痕欢唾，尚染鲛绡，凤迷归，破鸾慵舞。</p><p class="poem-stanza">殷勤待写，书中长恨，蓝霞辽海沈过雁，漫相思、弹入哀筝柱。</p><p class="poem-stanza">伤心千里江南，怨曲重招，断魂在否。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
